package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type action func(s *[]int) error

var builtin = map[string]action{
	"+": binOp(func(a, b int) (int, error) {
		return a + b, nil
	}),
	"-": binOp(func(a, b int) (int, error) {
		return a - b, nil
	}),
	"*": binOp(func(a, b int) (int, error) {
		return a * b, nil
	}),
	"/": binOp(func(a, b int) (int, error) {
		if b == 0 {
			return 0, errors.New("division by zero")
		}
		return a / b, nil
	}),
	"dup": func(s *[]int) error {
		v, err := pop(s)
		if err != nil {
			return err
		}
		*s = append(*s, v, v)
		return nil
	},
	"drop": func(s *[]int) error {
		_, err := pop(s)
		return err
	},
	"swap": func(s *[]int) error {
		b, err := pop(s)
		if err != nil {
			return err
		}
		a, err := pop(s)
		if err != nil {
			return err
		}
		*s = append(*s, b, a)
		return nil
	},
	"over": func(s *[]int) error {
		b, err := pop(s)
		if err != nil {
			return err
		}
		a, err := pop(s)
		if err != nil {
			return err
		}
		*s = append(*s, a, b, a)
		return nil
	},
}

func Forth(input []string) ([]int, error) {
	stack := []int{}
	defined := map[string][]action{}

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); {
			tok := tokens[i]
			if n, ok := parseNumber(tok); ok {
				stack = append(stack, n)
				i++
				continue
			}
			if strings.ToLower(tok) == ":" {
				next, err := parseDefinition(tokens, i+1, defined)
				if err != nil {
					return nil, err
				}
				i = next
				continue
			}
			body, err := resolve(tok, defined)
			if err != nil {
				return nil, err
			}
			for _, a := range body {
				if err := a(&stack); err != nil {
					return nil, err
				}
			}
			i++
		}
	}
	return stack, nil
}

func parseDefinition(tokens []string, i int, defined map[string][]action) (int, error) {
	if i >= len(tokens) {
		return i, errors.New("missing word name")
	}
	name := strings.ToLower(tokens[i])
	if _, isNum := parseNumber(tokens[i]); isNum {
		return i, errors.New("cannot redefine a number")
	}
	i++
	body := []action{}
	closed := false
	for ; i < len(tokens); i++ {
		if strings.ToLower(tokens[i]) == ";" {
			closed = true
			i++
			break
		}
		if n, ok := parseNumber(tokens[i]); ok {
			body = append(body, makePush(n))
			continue
		}
		a, err := resolve(tokens[i], defined)
		if err != nil {
			return i, err
		}
		body = append(body, a...)
	}
	if !closed {
		return i, errors.New("missing ;")
	}
	defined[name] = body
	return i, nil
}

func resolve(tok string, defined map[string][]action) ([]action, error) {
	name := strings.ToLower(tok)
	if body, ok := defined[name]; ok {
		return body, nil
	}
	if a, ok := builtin[name]; ok {
		return []action{a}, nil
	}
	return nil, fmt.Errorf("undefined operation: %s", tok)
}

func makePush(n int) action {
	return func(s *[]int) error {
		*s = append(*s, n)
		return nil
	}
}

func binOp(f func(a, b int) (int, error)) action {
	return func(s *[]int) error {
		a, b, err := popTwo(s)
		if err != nil {
			return err
		}
		v, err := f(a, b)
		if err != nil {
			return err
		}
		*s = append(*s, v)
		return nil
	}
}

func pop(s *[]int) (int, error) {
	if len(*s) == 0 {
		return 0, errors.New("empty stack")
	}
	v := (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	return v, nil
}

func popTwo(s *[]int) (int, int, error) {
	b, err := pop(s)
	if err != nil {
		return 0, 0, err
	}
	a, err := pop(s)
	if err != nil {
		return 0, 0, err
	}
	return a, b, nil
}

func parseNumber(tok string) (int, bool) {
	if tok == "" {
		return 0, false
	}
	start := 0
	if tok[0] == '-' {
		start = 1
	}
	if start >= len(tok) {
		return 0, false
	}
	for i := start; i < len(tok); i++ {
		if tok[i] < '0' || tok[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(tok)
	if err != nil {
		return 0, false
	}
	return n, true
}
